window.ScripturaLexicons.BDAG_PART_0171 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-01\" data-source=\"BDAG\" data-search=\"θυμίαμα, ατος, τό substantivo neutro incenso; queima de incenso; oferta de incenso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυμίαμα, ατος, τό</td><td>substantivo neutro</td><td>incenso; queima de incenso; oferta de incenso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-02\" data-source=\"BDAG\" data-search=\"θυμιατήριον, ου, τό substantivo neutro incensário; altar de incenso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυμιατήριον, ου, τό</td><td>substantivo neutro</td><td>incensário; altar de incenso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-03\" data-source=\"BDAG\" data-search=\"θυμιάω verbo queimar incenso; oferecer incenso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυμιάω</td><td>verbo</td><td>queimar incenso; oferecer incenso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-04\" data-source=\"BDAG\" data-search=\"θυμικός, ή, όν adjetivo irascível; colérico; de temperamento exaltado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυμικός, ή, όν</td><td>adjetivo</td><td>irascível; colérico; de temperamento exaltado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-05\" data-source=\"BDAG\" data-search=\"θυμομαχέω verbo estar muito irado; enfurecer-se contra alguém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυμομαχέω</td><td>verbo</td><td>estar muito irado; enfurecer-se contra alguém</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-06\" data-source=\"BDAG\" data-search=\"θυμός, οῦ, ὁ substantivo masculino paixão; desejo ardente; indignação; ira; furor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυμός, οῦ, ὁ</td><td>substantivo masculino</td><td>paixão; desejo ardente; indignação; ira; furor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-07\" data-source=\"BDAG\" data-search=\"θυμόω verbo irritar; enfurecer; ficar irado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυμόω</td><td>verbo</td><td>irritar; enfurecer; ficar irado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-08\" data-source=\"BDAG\" data-search=\"θύρα, ας, ἡ substantivo feminino porta; entrada; acesso; oportunidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θύρα, ας, ἡ</td><td>substantivo feminino</td><td>porta; entrada; acesso; oportunidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-09\" data-source=\"BDAG\" data-search=\"θυρεός, οῦ, ὁ substantivo masculino escudo comprido; escudo da fé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυρεός, οῦ, ὁ</td><td>substantivo masculino</td><td>escudo comprido; escudo da fé</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-10\" data-source=\"BDAG\" data-search=\"θυρίς, ίδος, ἡ substantivo feminino janela BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυρίς, ίδος, ἡ</td><td>substantivo feminino</td><td>janela</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-11\" data-source=\"BDAG\" data-search=\"θυρωρός, οῦ substantivo de dois gêneros porteiro; porteira; guardião da entrada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυρωρός, οῦ</td><td>substantivo de dois gêneros</td><td>porteiro; porteira; guardião da entrada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-12\" data-source=\"BDAG\" data-search=\"θυσία, ας, ἡ substantivo feminino ato de oferecer; sacrifício; oferta; oblação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυσία, ας, ἡ</td><td>substantivo feminino</td><td>ato de oferecer; sacrifício; oferta; oblação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-13\" data-source=\"BDAG\" data-search=\"θυσιαστήριον, ου, τό substantivo neutro altar; santuário; comunidade como altar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυσιαστήριον, ου, τό</td><td>substantivo neutro</td><td>altar; santuário; comunidade como altar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-14\" data-source=\"BDAG\" data-search=\"θύω verbo sacrificar; oferecer sacrifício; matar; abater; celebrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θύω</td><td>verbo</td><td>sacrificar; oferecer sacrifício; matar; abater; celebrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-15\" data-source=\"BDAG\" data-search=\"θῶ forma verbal remissiva ver τίθημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θῶ</td><td>forma verbal remissiva</td><td>ver τίθημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-16\" data-source=\"BDAG\" data-search=\"Θωμᾶς, ᾶ, ὁ nome próprio masculino Tomé; um dos doze apóstolos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θωμᾶς, ᾶ, ὁ</td><td>nome próprio masculino</td><td>Tomé; um dos doze apóstolos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-17\" data-source=\"BDAG\" data-search=\"θώραξ, ακος, ὁ substantivo masculino couraça; armadura para o peito; tórax BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θώραξ, ακος, ὁ</td><td>substantivo masculino</td><td>couraça; armadura para o peito; tórax</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-18\" data-source=\"BDAG\" data-search=\"ι´ sinal numeral grego dez; décimo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ι´</td><td>sinal numeral grego</td><td>dez; décimo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-19\" data-source=\"BDAG\" data-search=\"ια´ sinal numeral grego décimo primeiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ια´</td><td>sinal numeral grego</td><td>décimo primeiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0171-20\" data-source=\"BDAG\" data-search=\"Ἰάϊρος, ου, ὁ, nome próprio masculino Jairo; dirigente de sinagoga BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰάϊρος, ου, ὁ,</td><td>nome próprio masculino</td><td>Jairo; dirigente de sinagoga</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0171-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμίαμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete seguinte; Sófocles, Heródoto e posteriores; inscrições, papiros, LXX, pseudoepígrafos, Fílon, Josefo; Justino; Atenágoras 13, 1).</p><p class=\"entry-text\">① Substância aromática utilizada em ritos cultuais: incenso.</p><p class=\"entry-text\">ⓐ No singular (Heródoto 1, 198; PTebt 112, 22 [112 a.C.]; Josefo, Ant. 3, 197), B 2:5 (Is 1:13). Mais frequentemente:</p><p class=\"entry-text\">ⓑ No plural (Sófocles, Oed. R. 4; Heródoto 2, 86, 4; Platão, Rep. 2, 373a; SIG 999, 16s.; LXX, Fílon; Josefo, Ant. 4, 32), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:8</a>; 8:3s.; 18:13.</p><p class=\"entry-text\">② Queima cultual do incenso: incensação, oferta de incenso (LXX). <span class=\"greek\">τὸ</span> <span class=\"greek\">θυσιαστήριον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., «altar do incenso» (Êx 30:1, 27; 2Mc 2:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:11</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">ὥρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., «hora da oferta de incenso», v. 10. — DELG, s.v. 2 <span class=\"greek\">θύω</span> A4; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμιατήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete anterior; Heródoto, Tucídides e outros; inscrições, papiros, LXX; TestJob 32:8 e outros; ApcMos.) Em geral, local ou recipiente para queimar incenso (Kühner-Bl. II p. 281, 5), habitualmente um «incensário» (Heródoto 4, 162, 3; Tucídides 6, 46, 3; Eliano, VH 12, 51; POxy 521, 19 [séc. II d.C.]); mas, em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:4</a>, «altar do incenso» (como em SIG 996, 12 [séc. I d.C.?]; especialmente do altar do incenso no templo judaico: Fílon, Rer. Div. Her. 226; Mos. 2, 94; Josefo, Bell. 5, 218; Ant. 3, 147; 198). — New Docs 3, 69; DELG, s.v. 2 <span class=\"greek\">θύω</span> A4; M-M (com revisão da interpretação de Dittenberger sobre SIG2 583, 12 = SIG citado acima).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμιάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Futuro <span class=\"greek\">θυμιάσω</span>; 1º aoristo <span class=\"greek\">ἐθυμίασα</span> (ambos na LXX); infinitivo <span class=\"greek\">θυμιᾶσαι</span>. Passiva: aoristo <span class=\"greek\">ἐθυμιάθην</span>, LXX; particípio perfeito <span class=\"greek\">τεθυμιαμένη</span>, Ct 3:6 (ver os dois verbetes anteriores; Píndaro, Heródoto e outros; Diodoro Sículo 16, 11, 1; OGI 352, 37 [séc. II a.C.]; papiros [Kl. T. 135 n.º 5, 46]; LXX; TestSol 6:10; TestAbr A 4 p. 80, 22 [Stone p. 8]; Fílon; Josefo, Ant. 3, 199 e outros). Fazer uma oferta de incenso: <span class=\"greek\">ἔλαχεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυμιᾶσαι</span>, «coube-lhe por sorte oferecer incenso», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:9</a> (sobre a construção, cf. 1Km 14:47). — DELG, s.v. 2 <span class=\"greek\">θύω</span> A4; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">θυμός</span>; Aristóteles e outros; Fílon.) De temperamento exaltado, irascível (assim Aristóteles, Rhet. 2, 14 p. 1389a, 9; Cornuto 20 p. 39, 16; Ateneu 2, 45 p. 55s.; Taciano 9, 1), D 3:2. — DELG, s.v. <span class=\"greek\">θυμός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμομαχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">θυμός</span>, <span class=\"greek\">μάχομαι</span>.) Estar muito irado, com dativo <span class=\"greek\">τινί</span>, «com alguém» (Políbio 27, 8, 4, com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:20</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e posteriores.)</p><p class=\"entry-text\">① Expressão intensa do íntimo da pessoa, frequentemente manifestada como desejo vigoroso: paixão, anseio apaixonado (Homero e outros; Platão, Cratyl. 419e <span class=\"greek\">θυμὸς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θύσεως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ζέσεως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ψυχῆς</span>): <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἴνου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυμοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πορνείας</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">πεπότικεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἔθνη</span>, «ela fez as nações beberem do vinho de sua imoralidade apaixonada», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:8</a>; cf. 18:3. <span class=\"greek\">τὸ</span> <span class=\"greek\">ποτήριον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἴνου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θυμοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὀργῆς</span> <span class=\"greek\">αὐτοῦ</span>, «o cálice do vinho da ira apaixonada de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16:19</a>; cf. 19:15. Porém, em todos esses casos, a acepção 2 pode ser a correta; nas demais passagens do Apocalipse em que <span class=\"greek\">θ</span>. ocorre, provavelmente só é possível a acepção 2.</p><p class=\"entry-text\">② Estado de profundo desagrado: ira, cólera, furor, indignação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:12</a> (<span class=\"greek\">θυμὸν</span> <span class=\"greek\">ἔχειν</span>, como em Teógnis 748 Bergk). <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶνος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θυμοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «o vinho da ira ou indignação de Deus» (ver <span class=\"greek\">ἄκρατος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:10</a>; cf. v. 19; 15:1, 7; 16:1 (imagem do derramamento da ira frequente no AT).</p><p class=\"entry-text\">Se essa acepção for válida para todas as ocorrências no Apocalipse, a combinação dos genitivos de <span class=\"greek\">θυμός</span> e <span class=\"greek\">ὀργή</span> em 16:19; 19:15 deve ser entendida como reforço da ideia (cf. Êx 32:12; Jr 32:37; 37:24; Lm 2:3; CD 10, 9; En 5:9; PsSol 2:23; Atenágoras 21, 1); e, em 14:8; 18:3, há uma metáfora complexa (cf. Píndaro, P. 10, 51–54 e comentário de B. Gildersleeve sobre metáfora «telescópica» [Pindar: The Olympian and Pythian Odes, 1885, 355]): o vinho da prostituição, com que Babilônia embriaga as nações, torna-se para elas o vinho da ira de Deus.</p><p class=\"entry-text\">Nas demais ocorrências de <span class=\"greek\">θ</span>. nesta literatura, indica-se o mesmo significado: de Deus (com <span class=\"greek\">ὀργή</span>; ambas as palavras são frequentemente usadas juntas na LXX), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:8</a>; 1Cl 50:4. De seres humanos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:27</a>; (com <span class=\"greek\">ὀργή</span>, como Eliano, VH 15, 54; Élio Aristides 35, 10 K. = 9 p. 101 D.; Herodiano 8, 4, 1; Sir 45:18; Josefo, Bell. 2, 135; Ant. 20, 108), Cl 3:8; (com <span class=\"greek\">πικρία</span> e <span class=\"greek\">ὀργή</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:31</a>; cf. Hm 5, 2, 4 e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:11</a>, P74. <span class=\"greek\">ἐξερίσαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοσοῦτο</span> <span class=\"greek\">θυμοῦ</span>, «chegar a tamanho grau de furor», 1Cl 45:7; <span class=\"greek\">ἀκατάσχετος</span> <span class=\"greek\">θ</span>., «ira irrefreável», MPol 12:2. <span class=\"greek\">πλησθῆναι</span> <span class=\"greek\">θυμοῦ</span>, «encher-se de ira», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:28</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:28</a>.</p><p class=\"entry-text\">No plural, <span class=\"greek\">θυμοί</span> (Herm. Wr. 12, 4; Fílon, Rer. Div. Her. 64; Josefo, Bell. 4, 314), «explosões de ira», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:20</a>; 1Cl 46:5. — J. Irmscher, Götterzorn bei Homer, ’50; S. Sullivan, Glotta 59, ’81, 147–55 (Hesíodo e poetas líricos gregos); B. 1087; 1134; DELG; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo, 3ª pessoa do singular <span class=\"greek\">ἐθύμωσεν</span>, Os 12:15; passiva <span class=\"greek\">ἐθυμώθην</span>; futuro <span class=\"greek\">θυμωθήσομαι</span>, LXX (ver <span class=\"greek\">θυμός</span>; Ésquilo, Heródoto e outros; Díon Crisóstomo 10 [11], 20; LXX; TestSol 20:6; JosAs; ParJer 6:23 [códice C]; EpArist 254; Josefo, Bell. 1, 221; Ant. 12, 270). Fazer ficar irado; na passiva, ficar irado. Uso absoluto (Políbio 5, 16, 4; TestDan 4:4; TestSol 20:6): <span class=\"greek\">ἐθυμώθη</span> <span class=\"greek\">λίαν</span>, «ficou extremamente irado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:16</a>. Em GJs 22:1, variante de leitura em lugar de <span class=\"greek\">ὀργισθείς</span>. — DELG, s.v. <span class=\"greek\">θυμός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e posteriores.) «Porta». Como muitas vezes na literatura mais antiga (por exemplo, Ilíada e Odisseia, passim), o plural pode designar uma única porta (Flégon: 257 Fgm. 36, 1, 3 Jac.; Fílon, Ebr. 49; cf. Josefo, C. Ap. 2, 119. — B-D-F §141, 4; Rob. 408).</p><p class=\"entry-text\">① Porta.</p><p class=\"entry-text\">ⓐ De habitações. <span class=\"greek\">ἀνοίγειν</span>, «abrir a porta» (LXX; JosAs 10:9; Josefo, Vi. 246), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:19</a>; B 16:9. Na passiva, At 16:26s. (Aquiles Tácio 7, 13, 1 <span class=\"greek\">Λευκίππη</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">θύρας</span> <span class=\"greek\">ἀνεῳγμένας</span> <span class=\"greek\">ὁρῶσα</span>). (<span class=\"greek\">ἀπο</span>)<span class=\"greek\">κλείειν</span>, «fechar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:25a</a>. Na passiva (LXX; JosAs 10:6; 14:5; Josefo, Ant. 18, 74), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20:19</a>, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:30</a>. <span class=\"greek\">κρούειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θ</span>., «bater à porta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:25b</a>; também <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θ</span>., GJs 12:2; <span class=\"greek\">ἔδραμεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τήν</span> <span class=\"greek\">θ</span>., ibid. <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>., Jo 10:1s.</p><p class=\"entry-text\"><span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θυρῶν</span>, «diante da porta (ou das portas)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:23</a>. Também <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θύραις</span> (LXX; Esopo, Fab. 466 P.; Josefo, Ant. 17, 90; com artigo, Clearco, Fgm. 24 p. 17, 21; Apiano, Bell. Civ. 3, 93 §385), 1Cl 39:9 (Jó 5:4); <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:9</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θύρας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:6</a> (escólio a Nicandro, Ther. 860 <span class=\"greek\">πρὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θυρῶν</span>); também JosAs 5:1. <span class=\"greek\">πρὸς</span> (<span class=\"greek\">τὴν</span>) <span class=\"greek\">θ</span>., «à porta» (Hegesipo Cômico [séc. III a.C.] 1, 24 K.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:33</a>; 11:4; <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θ</span>., «o lugar próximo da porta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:2</a> (TestAbr A 6 p. 83, 6 [Stone p. 14]). <span class=\"greek\">πρὸς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἔξω</span>, «fora da porta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18:16</a> (cf. Luciano, Herm. 7, 7 <span class=\"greek\">ὁ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">ἑστώς</span>).</p><p class=\"entry-text\">— <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span>, «porta da torre», Hv 3, 9, 6. — Sobre a <span class=\"greek\">θύρα</span> <span class=\"greek\">ὡραία</span>, «Porta Formosa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:2</a>, ver <span class=\"greek\">ὡραῖος</span> 2. — 1Cl 43:3, variante de leitura.</p><p class=\"entry-text\">ⓑ Uso figurado (Máximo de Tiro 19, 5d <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔρως</span> <span class=\"greek\">ἔστη</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θύραις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ψυχῆς</span>; Jâmblico, Myst. 10, 5 [Herm. Wr. IV p. 39, 5ss. Sc.] <span class=\"greek\">ἡ</span> <span class=\"greek\">ἱερατικὴ</span> <span class=\"greek\">δόσις</span> <span class=\"greek\">καλεῖται</span> ‘<span class=\"greek\">θύρα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεόν</span>’).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">ἐγγύς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θύραις</span>, «ele está próximo, à própria porta» (cf. Xenofonte, An. 6, 5, 23; Justino, D. 32, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:29</a>. Também <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θυρῶν</span> <span class=\"greek\">ἕστηκεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:9</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:9</a>. <span class=\"greek\">ἕστηκα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θύραν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κρούω</span>, «estou à porta e bato», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:20a</a>; ver também v. 20b.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Da porta que dá acesso ao reino dos céus: <span class=\"greek\">εἰσελθεῖν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">στενῆς</span> <span class=\"greek\">θύρας</span>, «entrar pela porta estreita», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:24</a>. Talvez se refira à mesma porta em <span class=\"greek\">δέδωκα</span> <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">σου</span> <span class=\"greek\">θύραν</span> <span class=\"greek\">ἠνεῳγμένην</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:8</a>. Contudo, aqui também é provável a acepção seguinte:</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. A abertura da porta representa algo tornado possível ou viável: <span class=\"greek\">θύρα</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἀνέῳγεν</span> <span class=\"greek\">μεγάλη</span>, «abriu-se para mim uma grande porta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16:9</a> (H. Nie, Vox Theologica 10, ’40, 185–92); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:12</a>; Cl 4:3. Similarmente, <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> … <span class=\"greek\">ἤνοιξεν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔθνεσιν</span> <span class=\"greek\">θύραν</span> <span class=\"greek\">πίστεως</span>, «Deus abriu aos gentios uma porta de fé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:27</a> (<span class=\"greek\">πίστις</span> 2d<span class=\"greek\">α</span>).</p><p class=\"entry-text\">② Passagem para entrar numa estrutura: entrada, vão, portal.</p><p class=\"entry-text\">ⓐ Abertura semelhante a uma porta em sepulcro escavado na rocha (cf. Od. 9, 243; SEG VIII, 200, 3 [séc. I d.C., Jerusalém]): <span class=\"greek\">ἡ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μνημείου</span>, «a entrada do sepulcro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:60</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:46</a>; 16:3. <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μνήματος</span>, GPt 8:32; cf. 9:37; 12:53s. — A abóbada firme do céu tem uma «porta» (cf. Sl 77:23), que se abre para admitir pessoas favorecidas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:1</a> (interpretação diversa em G. Rinaldi, CBQ 25, ’63, 336–47).</p><p class=\"entry-text\">ⓑ Em João, Jesus chama a si mesmo <span class=\"greek\">ἡ</span> <span class=\"greek\">θύρα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:9</a>, retratando-se como abertura que permite a passagem: «a porta para as ovelhas». <span class=\"greek\">ἡ</span> <span class=\"greek\">θύρα</span> (<span class=\"greek\">ὁ</span> <span class=\"greek\">ποιμήν</span>, P75 e outros) <span class=\"greek\">τῶν</span> <span class=\"greek\">προβάτων</span>, v. 7, contudo, tem o sentido que predomina no contexto: «a porta de acesso às ovelhas» (ver Hdb., ad loc.; E. Fascher, Ich bin d. Thür!, Deutsche Theologie, ’42, 34–57; 118–33). — Jesus como <span class=\"greek\">θύρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>, «a porta para o Pai», IPhld 9:1. — B. 466; DELG; M-M; EDNT; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυρεός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Políbio 6, 23, 2; Diodoro Sículo 5, 18, 3; 5, 33, 4 e outros; PSI 428, 36 [séc. III a.C.]; LXX; Josefo, Ant. 8, 179; SibOr 3, 729; empréstimo no hebraico rabínico.) Propriamente «escudo longo e oblongo» (com formato de porta: ver <span class=\"greek\">θύρα</span>), escudo; figuradamente <span class=\"greek\">θ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, «escudo da fé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:16</a>. A. Botuno, La metafora della porta: RivB 39, ’91, 207–15. — B. 1402; DELG, s.v. <span class=\"greek\">θύρα</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυρίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">θύρα</span>.) Janela (assim Aristóteles e posteriores; inscrições, papiros, LXX; En 101:2; TestJos 14:1; JosAs; Fílon, Plant. 169; Josefo; empréstimo no hebraico rabínico). <span class=\"greek\">καθέζεσθαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>., «sentar-se à janela», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:9</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">θυρίδος</span>, «pela janela», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:33</a> (Paléfato p. 20, 5; UPZ 15, 7; 53, 5; Js 2:15; 1Km 19:12; Josefo, Bell. 6, 252; Ant. 6, 217; sobre incidentes semelhantes, ver Wetstein: Ateneu 5, 52 p. 214a e Plutarco, Aemil. Paul. 26, 269a). <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ταύτης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θυρίδος</span>, AcPl Ox 6, reto, 5s. (= Aa I 241, 12). — DELG, s.v. <span class=\"greek\">θύρα</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυρωρός, οῦ</h1><div class=\"entry-meta\"><span>substantivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Porteiro, guardião da entrada. <span class=\"greek\">ὁ</span>, de um homem (ver <span class=\"greek\">θύρα</span>; Safo e outros; papiros, LXX; TestJob 43:6; Josefo, Ant. 11, 108): «porteiro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:34</a>; «guardião da entrada», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:3</a>. <span class=\"greek\">ἡ</span>, de uma mulher, «porteira» (BGU 1061, 10 [14 a.C.]; PRyl 36, 6 [34 d.C.]; PStras 24:17; 2Km 4:6; TestJob; JosAs 10:3; Josefo, Ant. 7, 48), Jo 18:16s. (M. Black, An Aramaic Approach3, ’67, 258s. [siríaco sinaítico]). — DELG, s.v. <span class=\"greek\">θύρα</span>; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">θύω</span> e verbete seguinte; Píndaro, Heródoto e posteriores.)</p><p class=\"entry-text\">① Ato de oferecer: oferta, figuradamente <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θυσίᾳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πίστεως</span> <span class=\"greek\">ὑμῶν</span>, «ao oferecerdes vossa fé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:17</a> (embora a acepção 2b não seja impossível para o complexo conjunto de imagens desta passagem; ver abaixo).</p><p class=\"entry-text\">② Aquilo que é oferecido como sacrifício: sacrifício, oferta.</p><p class=\"entry-text\">ⓐ Literalmente.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Em geral (Dg 3:5; Justino, D. 43, 1 e outros; Atenágoras 26, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:13</a>; 12:7 (ambos em Os 6:6); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:49</a>, variante de leitura, ver <span class=\"greek\">ἁλίζω</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:5</a> (Sl 39:7), 26. No plural, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:1</a> (cf. Josefo, Bell. 2, 30 <span class=\"greek\">παρὰ</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἰδίαις</span> <span class=\"greek\">θυσίαις</span> <span class=\"greek\">ἀπεσφάχθαι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:1</a>, 8; 1Cl 4:2 (Gn 4:5; cf. Diodoro Sículo 12, 20, 2 <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">χαιρόντων</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πονηρῶν</span> <span class=\"greek\">θυσίαις</span>); B 2:4, 5 (Is 1:11), 7 (Jr 7:22).</p><p class=\"entry-text\">Especificam-se os diversos tipos em 1Cl 41:2. <span class=\"greek\">ἀνάγειν</span> <span class=\"greek\">θυσίαν</span>, «trazer uma oferta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.41\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:41</a> (<span class=\"greek\">ἀνάγω</span> 3). Também <span class=\"greek\">ἀναφέρειν</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:27</a> (<span class=\"greek\">ἀναφέρω</span> 3); <span class=\"greek\">δοῦναι</span> <span class=\"greek\">θ</span>., «dar uma oferta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:24</a>. <span class=\"greek\">προσφέρειν</span>, «oferecer» (Êx 32:6; Lv 2:1, 8 e frequentemente; Justino, D. 41, 3 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:42</a> (Am 5:25); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:1</a>; 8:3; 10:11; 11:4; 1Cl 10:7. Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:9</a>. <span class=\"greek\">φέρειν</span> <span class=\"greek\">θ</span>. (2Cr 29:31; Jr 17:26; Justino, A I, 24, 2 e outros), 1Cl 4:1 (Gn 4:3). <span class=\"greek\">προσάγεσθαι</span> <span class=\"greek\">θ</span>. (cf. 1Esd 1:16), «ser conduzido como sacrifício», 1Cl 31:3.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. De uma refeição sacrificial (Polícrates: 588 Fgm. 1 Jac., equiparado a <span class=\"greek\">θοίνη</span> [«banquete»]; Pseudo-Calístenes 3, 29, 9 <span class=\"greek\">τὴν</span> <span class=\"greek\">θυσίαν</span> <span class=\"greek\">ἐποιησάμεθα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Σωτηρίων</span>, «a refeição para celebrar a libertação»): <span class=\"greek\">ἐσθίειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">θ</span>., «comer dos sacrifícios» (Sl 105:28; Nm 25:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:18</a>. A Eucaristia é mencionada como sacrifício ou oferta e refeição sacrificial em D 14:1ss. (ver Knopf, Hdb., excursus a D 9 e 10, p. 24s.).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Da morte sacrificial de Cristo, que, em contraste com sacrifícios terrenos, deve ser contada entre as <span class=\"greek\">κρείττονες</span> <span class=\"greek\">θυσίαι</span>, «sacrifícios superiores», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:23</a>; 10:12. <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θυσίας</span> <span class=\"greek\">αὐτοῦ</span>, «por meio de seu sacrifício», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:26</a>. <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">θυσίαν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεῷ</span>, «entregou-se por nós como sacrifício a Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:2</a> (Diodoro Sículo 4, 82, 2 <span class=\"greek\">τὴν</span> <span class=\"greek\">θυσίαν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἁπάντων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἑλλήνων</span>). — B 7:3. — A respeito da aspiração ao martírio: <span class=\"greek\">ἵνα</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀργάνων</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">θυσία</span> <span class=\"greek\">εὑρεθῶ</span>, «para que, por meio desses instrumentos, eu seja encontrado como sacrifício de Deus», IRo 4:2. <span class=\"greek\">προσδεχθείην</span> … <span class=\"greek\">σήμερον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θυσίᾳ</span> <span class=\"greek\">πίονι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προσδεκτῇ</span>, MPol 14:2.</p><p class=\"entry-text\">ⓑ Figuradamente (Sexto 47: fazer o bem como única <span class=\"greek\">θυσία</span> agradável a Deus; igualmente Pérsio 2, 73–75, o coração puro como sacrifício apropriado aos templos: compositum ius fasque animo … haec cedo ut admoveam templis). Um espírito quebrantado é designado <span class=\"greek\">θ</span>., 1Cl 18:16s.; 52:4; B 2:10 (todos os três em Sl 50:19). <span class=\"greek\">θ</span>. <span class=\"greek\">αἰνέσεως</span>, «oferta de louvor» (ver <span class=\"greek\">αἴνεσις</span>), é usado figuradamente nesta literatura acerca do sacrifício espiritual: 1Cl 35:12 (Sl 49:23); 52:3 (Sl 49:14). Explica-se em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:15</a> como <span class=\"greek\">καρπὸς</span> <span class=\"greek\">χειλέων</span> <span class=\"greek\">ὁμολογούντων</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">αὐτοῦ</span> (= <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>).</p><p class=\"entry-text\"><span class=\"greek\">εἰ</span> <span class=\"greek\">σπένδομαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θυσίᾳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">ὑμῶν</span>, «ainda que eu tenha de derramar meu sangue sobre o sacrifício de vossa fé» (isto é, que consiste em vossa fé), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:17</a> (cf. Arriano, Anab. 6, 19, 5 <span class=\"greek\">σπείσας</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θυσίᾳ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φιάλην</span>; mas ver 1 acima). <span class=\"greek\">θ</span>. <span class=\"greek\">δεκτή</span>, «sacrifício aceitável» (ver <span class=\"greek\">δεκτός</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:18</a>; Hs 5, 3, 8; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:16</a> e o final de 2a<span class=\"greek\">γ</span>.</p><p class=\"entry-text\"><span class=\"greek\">πνευματικαὶ</span> <span class=\"greek\">θ</span>., «sacrifícios espirituais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:5</a> (cf. Herm. Wr. 13, 18; 19; 21 <span class=\"greek\">λογικαὶ</span> <span class=\"greek\">θυσίαι</span>; sobre isso, ver Rtzst., Mysterienrel.3 38; 328s. — SibOr 8, 408 <span class=\"greek\">ζῶσα</span> <span class=\"greek\">θυσία</span>). <span class=\"greek\">παρακαλῶ</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">παραστῆσαι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σώματα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">θυσίαν</span> <span class=\"greek\">ζῶσαν</span>, «rogo-vos que apresenteis vossos corpos como sacrifício vivo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12:1</a> (<span class=\"greek\">παριστάναι</span> <span class=\"greek\">θυσίαν</span> é termo técnico do procedimento sacrificial: OGI 332, 17 e 42; 456, 20s.; 764, 23 e 33 e outros; SIG2 554, 6; SIG3 694, 50. — P. Seidensticker, Lebendiges Opfer Röm 12:1, tese, Münster, ’54).</p><p class=\"entry-text\">— O. Schmitz, Die Opferanschauung d. spät. Judentums u. die Opferaussagen d. NTs, 1910; H. Wenschkewitz, D. Spiritualisierung der Kultusbegriffe Tempel, Priester u. Opfer im NT, ’32; W. von Loewenich, Z. Verständnis d. Opfergedankens im Hb: ThBl 12, ’32, 167–72; J. Brinktrine, D. Messopferbegr. in den ersten 2 Jahrh., 1918; R. Yerkes, ATR 29, ’47, 28–33; R. de Vaux, Les Sacrifices de l’Ancien Testament, ’64; BHHW II 1345–52; Pauly-W. XVIII 579–627; J. Casabona, Recherches sur le vocabulaire des Sacrifices en Grec, ’66. — B. 1467; DELG, s.v. 2 <span class=\"greek\">θύω</span> B6; TRE XXV, especialmente 253–78; M-M; Sv. Ver também <span class=\"greek\">εὐχαριστία</span> 3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυσιαστήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete anterior; LXX; pseudoepígrafos; Fílon, Mos. 2, 105; Josefo, Ant. 8, 88; 105; Justino, D. 118, 2; geralmente «altar»).</p><p class=\"entry-text\">① Estrutura em que se realizam observâncias cultuais, especialmente sacrifícios: altar.</p><p class=\"entry-text\">ⓐ Do altar dos holocaustos, no átrio interno do templo de Jerusalém (ver Schürer II 298s.), Mt 5:23s.; 23:18–20, 35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:1</a>; 1Cl 41:2; B 7:9 (cf. Lv 16:7–9, 18). <span class=\"greek\">λειτουργεῖν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>., «servir no altar», 1Cl 32:2; <span class=\"greek\">παρεδρεύειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>. (ver <span class=\"greek\">παρεδρεύω</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:13a</a>; <span class=\"greek\">συμμερίζεσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>. (ver <span class=\"greek\">συμμερίζω</span>), v. 13b; <span class=\"greek\">κοινωνοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., «participantes, associados ao altar», isto é, intimamente unidos ao altar (= a Deus; ver 10:20), 10:18 (ver <span class=\"greek\">κοινωνός</span> 1b<span class=\"greek\">α</span>; mas ver G. Jourdan, JBL 67, ’48, 122s.). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:35</a> e, portanto, provavelmente também GJs 5:1; 7:3; 8:2; 23:1; 24:2.</p><p class=\"entry-text\">ⓑ Do altar de incenso.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. No templo de Jerusalém: <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυμιάματος</span>, «o altar do incenso» (Êx 30:1, 27), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:11</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. O altar celeste do Apocalipse também parece ser concebido como um altar de incenso: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:9</a>; 8:3, 5; 9:13; 14:18; 16:7. Hermas também fala de um <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «altar de Deus», no céu, Hm 10, 3, 2s.; Hs 8, 2, 5.</p><p class=\"entry-text\">ⓒ De um altar em geral: o erigido por Abraão (Gn 22:9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2:21</a>; B 7:3. Plural: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:3</a> (3Km 19:10).</p><p class=\"entry-text\">ⓓ Diversos outros referentes, sobretudo extensões figuradas dos anteriores.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Em IRo 2:2, Inácio fala do altar preparado para receber sua morte como mártir.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Em Pol 4:3, as viúvas cristãs são chamadas <span class=\"greek\">θυσιαστήριον</span> <span class=\"greek\">θεοῦ</span>, «altar de Deus», pois devem apresentar a Deus somente dons perfeitos (cf. Sexto 46b, o coração puro como <span class=\"greek\">θ</span>. para Deus).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. A passagem <span class=\"greek\">ἔχομεν</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχουσιν</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σκηνῇ</span> <span class=\"greek\">λατρεύοντες</span>, «temos um altar do qual os que servem ao tabernáculo não têm direito de comer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:10</a>, é difícil. Estudiosos como F. Bleek, A. Seeberg e B. Haensler, BZ 11, 1913, 403–9, interpretam <span class=\"greek\">θ</span>. como a cruz de Cristo; outros (por exemplo, T. Haering, Der Brief an die Hebr., 1925, 103), como a mesa de comunhão. H. Windisch rejeita ambas as interpretações. B. Weiss e E. Riggenbach2, 3, 1922, desistem de tentar compreendê-la. Ver também J. Creed, ET 50, ’38, 13–15; J. Wilson, ibid., 380s.; J. Oulton, ibid. 55, ’44, 303–5. — <span class=\"greek\">προσέρχεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">λειτουργεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:9</a>, variante de leitura, também deve ser interpretado à luz das instituições cristãs.</p><p class=\"entry-text\">② O povo de Deus como entidade cultual: santuário, em linguagem figurada. <span class=\"greek\">ἐντὸς</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">θ</span>. <span class=\"greek\">εἶναι</span>, «estar dentro do santuário» (<span class=\"greek\">θ</span>., neste sentido, talvez também em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:18</a> e Procópio, Aed. 1, 65; inscrição em <span class=\"greek\">Ἀρχαιολογικὸν</span> <span class=\"greek\">Δελτίον</span> 12, 1927, 69), isto é, a comunidade ou igreja cristã sob o cuidado e a supervisão de suas autoridades constituídas, IEph 5:2; ITr 7:2 (em oposição a <span class=\"greek\">ἐκτὸς</span> <span class=\"greek\">θ</span>.). Isso concorda com a afirmação enfática de Inácio de que existe apenas um <span class=\"greek\">θ</span>., IMg 7:2; IPhld 4. — B. 1467; DELG, s.v. 2 <span class=\"greek\">θύω</span> B6; EDNT; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἔθυον</span>; futuro <span class=\"greek\">θύσω</span>, LXX; 1º aoristo <span class=\"greek\">ἔθυσα</span>; perfeito <span class=\"greek\">τέθυκα</span>, LXX. Passiva: 1º aoristo <span class=\"greek\">ἐτύθην</span>; particípio <span class=\"greek\">τυθείς</span> (Justino, D. 111, 3), <span class=\"greek\">θυθείς</span> (Melitão, P. 71, 516 [B]); particípio perfeito <span class=\"greek\">τεθυμένος</span> (Homero e posteriores).</p><p class=\"entry-text\">① Fazer uma oferta cultual: sacrificar (é o significado primário e o mais frequente); construção <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, «sacrificar algo em honra de alguém» (Diodoro Sículo 16, 18, 5; 17, 100, 1; Luciano, Dial. Deor. 2, 4; SIG 589, 48; 993, 11s.; Gn 46:1; Josefo, Bell. 2, 214 <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">χαριστήρια</span>; SibOr 3, 626), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:20</a> (Dt 32:17). <span class=\"greek\">τ</span>. <span class=\"greek\">θεῷ</span> <span class=\"greek\">θυσίαν</span>, «oferecer um sacrifício a Deus», 1Cl 52:3 (Sl 49:14).</p><p class=\"entry-text\">Com dativo <span class=\"greek\">τινί</span>, «em honra de alguém» (Xenofonte, Cyr. 8, 7, 3; Mitt-Wilck. I/2, 116, 2 <span class=\"greek\">θύε</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>; BGU 287, 7; LXX; EpArist 138; Josefo, Bell. 1, 56 <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>; Justino, D. 46, 7; 136, 3 <span class=\"greek\">τῇ</span> <span class=\"greek\">Βάαλ</span>; Atenágoras 1, 1 <span class=\"greek\">Ποσειδῶνι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:18</a>; 2Cl 3:1. Uso absoluto (Luciano, Jupp. Trag. 22, início; PHib 28, 7; LXX; Atenágoras 13, 1; 26, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:13</a>; MPol 12:2.</p><p class=\"entry-text\">(Usado também em relação a sacrifícios humanos: Apolodoro [séc. II a.C.]: 244 Fgm. 125 Jac. = Porfírio, De Abst. 2, 55; Aristides 9, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span> <span class=\"greek\">τέκνα</span>, «os próprios filhos», a Cronos; Justino, D. 19, 6 <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐθύετε</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">δαιμονίοις</span> e outros.)</p><p class=\"entry-text\">② Tirar a vida: matar, abater, em sentido geral.</p><p class=\"entry-text\">ⓐ Seres humanos (Eurípides, Iph. T. 621; Sir 34:20; 1Mc 7:19); uso absoluto na imagem agrícola de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:10</a>, que também exige sua colocação em b.</p><p class=\"entry-text\">ⓑ Animais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:10</a> (G. Kilpatrick, BT 12, ’61, 130–32, «matar para servir de alimento»; nesse sentido também a morte de um galo por ladrões, Esopo, Fab. 122 P. = 195 H.; ovelhas, 143 P. = 262 H.; bois [abatidos sem recorrer a açougueiros profissionais], 290 P. = Bábrio 21. Ver também Tb 7:8; Josefo, Ant. 1, 197 <span class=\"greek\">μόσχον</span>; Taciano 23, 2 <span class=\"greek\">ζῶα</span>); um bezerro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:23</a>, 27, 30; na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:4</a>.</p><p class=\"entry-text\">③ Matar cerimonialmente: abater para sacrifício (sobre a estreita relação entre sacrificar e abater, ver Lietzmann, Hdb., em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:25</a>). <span class=\"greek\">τὸ</span> <span class=\"greek\">πάσχα</span>, «o cordeiro pascal» (Êx 12:21; Dt 16:2, 5s.; 1Esd 1:6; 7:12), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:12</a>. Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:7</a>; daí <span class=\"greek\">τὸ</span> <span class=\"greek\">πάσχα</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἐτύθη</span> <span class=\"greek\">Χριστός</span>, «Cristo foi sacrificado como nossa Páscoa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5:7</a> (Justino, D. 111, 3; Melitão, P. 71, 516 B.; sobre <span class=\"greek\">θύω</span> aplicado ao sacrifício de uma pessoa, ver 1 acima). Uso absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:13</a>; 11:7.</p><p class=\"entry-text\">④ Celebrar, talvez somente quando um animal é abatido em conexão com a celebração (Polieno 1, 44, <span class=\"greek\">θ</span>. <span class=\"greek\">εὐαγγέλια</span>, «festival jubiloso»; Apiano, Syr. 4 §17; 16 §69 <span class=\"greek\">γάμους</span>, em ambas as passagens; Ateneu 12, 43, 532e <span class=\"greek\">θ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπινίκια</span>; Aquiles Tácio 8, 19, 3 <span class=\"greek\">θ</span>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">γάμους</span>. — Filócoro n.º 328 Fgm. 65 Jac. usa <span class=\"greek\">θυσία</span> para festividades familiares domésticas), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:7</a> (ver 3 acima). — DELG, s.v. 2 <span class=\"greek\">θύω</span> B1; TRE XXV 253–71; M-M; EDNT; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θῶ</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Ver <span class=\"greek\">τίθημι</span>. — DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θωμᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(O aramaico תְּאוֹמָא = «gêmeo», que jamais foi usado apenas como sobrenome [M. Lidzbarski, Handb. der nordsem. Epigraphik, 1898, 383], acabou por coincidir, nas regiões de língua grega, com o nome grego <span class=\"greek\">Θωμᾶς</span> [R. Herzog, Philol 56, 1897, 51]; ver Dalman, Gramm.2 145, 6; Wuthnow 55; B-D-F §53, 2d; 125, 2.) Tomé, um dos 12 apóstolos (ver <span class=\"greek\">Δίδυμος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:16</a>; 14:5; 20:24, 26–28; 21:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:13</a>; Ox 654, 3 (GTh 1) = ASyn. 247, 19; Pápias (2:4). — BHHW III 1974; M-M; EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θώραξ, ακος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">① Cobertura de proteção do peito em combate: couraça (assim Homero e posteriores; ChronLind 36; 41; 47; PPetr III, 6a, 28 [237 a.C.]; PGiss 47, 6; LXX; TestJud 3:5; Fílon, Leg. All. 3, 115; Josefo, Ant. 8, 414; Vi. 293; empréstimo no hebraico rabínico), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:9b</a>, 17. Figuradamente, <span class=\"greek\">ἐνδύεσθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θώρακα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span>, «vestir a couraça da justiça», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:14</a> (cf. Is 59:17; Sb 5:18). <span class=\"greek\">θ</span>. <span class=\"greek\">πίστεως</span>, «couraça da fé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:8</a>.</p><p class=\"entry-text\">② Parte do corpo coberta pela couraça: peito, tórax (Eurípides; Platão, Tim. 69e; Aristóteles, Hist. An. 1, 7; Diodoro Sículo 15, 87, 1; 5; Polieno 3, 9, 22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:9a</a> (embora a acepção 1 não esteja excluída). — B. 1399; DELG; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ι´</h1><div class=\"entry-meta\"><span>sinal numeral grego</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Sinal numérico = 10 (<span class=\"greek\">δέκα</span>: Josefo, C. Ap. 1, 157; cf. SibOr 5, 14), B 9:8 (<span class=\"greek\">ἰῶτα</span> nos códices HV); Hs 9, 3, 3; 9, 4, 2; 3; 9, 5, 4; 9, 15, 4; ou «10º» (<span class=\"greek\">δεκάτη</span>), Hm 10, sobrescrito.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ια´</h1><div class=\"entry-meta\"><span>sinal numeral grego</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Sinal numérico = «11º» (<span class=\"greek\">ἑνδεκάτη</span>), Hm 11, sobrescrito.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0171-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰάϊρος, ου, ὁ,</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ἰάειρος</span>, segundo W-H. (= יָאִיר, «ele ilumina», ou, raramente [1Cr 20:5], = יָעִיר, «ele desperta»). Jairo (<span class=\"greek\">Ἰαί̈ρ</span>, Nm 32:41; Dt 3:14; 1Cr 2:22s. e outros; <span class=\"greek\">Ἰάϊρος</span>, 1Esd 5:31; Et 1:1a; Josefo, Bell. 2, 447; ver P. Thomsen, Inschr. d. Stadt Jerusalem [= ZDPV 43, 1920, 138ss.] n.º 190; O. Wilck II, 1231), um dirigente de sinagoga, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:41</a> (sobre o título, ver SEG XLIII, 1297 [bibliografia]). — M-M.</p></section></article>\n"};
